/// <summary>
/// ATL entity for one MD31 input row (SJPMDItemMaster), written by hand on the pattern of
/// the generated ATL entities (AtlEntityASOHClassDefault in AtlApplicationSuite).
/// A new row starts as Status = New, ErrorFlag = No, ProcessingGroup = 0, which is what the
/// file import leaves behind: SJPMDInventImportStatus has no zero element (New = 1).
/// </summary>
public final class TEST_AtlEntityMD31ItemMasterRow extends AtlEntity
{
    private SJPMDItemMaster itemMaster;
}

Method.Source:
protected void new(boolean _initValue = true)
{
    if (_initValue)
    {
        itemMaster.initValue();
        itemMaster.Status          = SJPMDInventImportStatus::New;
        itemMaster.ErrorFlag       = NoYes::No;
        itemMaster.ProcessingGroup = 0;
    }
}

public static TEST_AtlEntityMD31ItemMasterRow construct()
{
    return new TEST_AtlEntityMD31ItemMasterRow();
}

public TEST_AtlEntityMD31ItemMasterRow save()
{
    this.saveBase();

    return this;
}

/// <summary>
/// Sets one field and returns the entity, so every fluent setter is one line.
/// </summary>
private TEST_AtlEntityMD31ItemMasterRow setField(FieldId _fieldId, anytype _value)
{
    this.parmMainRecordField(_fieldId, _value, true);

    return this;
}

public TEST_AtlEntityMD31ItemMasterRow setFileName(Filename _fileName)
{
    return this.setField(fieldNum(SJPMDItemMaster, file_name), _fileName);
}

public TEST_AtlEntityMD31ItemMasterRow setCompanyCode(SJPMDItemMasterCompanyCode _companyCode)
{
    return this.setField(fieldNum(SJPMDItemMaster, crp_cd), _companyCode);
}

public TEST_AtlEntityMD31ItemMasterRow setSkuCode(SJPMDItemMasterJANCode _skuCode)
{
    return this.setField(fieldNum(SJPMDItemMaster, sku_cd), _skuCode);
}

public TEST_AtlEntityMD31ItemMasterRow setSellEnd(SJPMDItemMasterSalesEndDate _yyyymmdd)
{
    return this.setField(fieldNum(SJPMDItemMaster, sel_tm_en), _yyyymmdd);
}

public TEST_AtlEntityMD31ItemMasterRow setCaseSize(
    SJPMDItemMasterCaseDepth  _depth,
    SJPMDItemMasterCaseWidth  _width,
    SJPMDItemMasterCaseHeight _height)
{
    this.setField(fieldNum(SJPMDItemMaster, oc_depth),  _depth);
    this.setField(fieldNum(SJPMDItemMaster, oc_width),  _width);
    return this.setField(fieldNum(SJPMDItemMaster, oc_height), _height);
}

public TEST_AtlEntityMD31ItemMasterRow setCaseWeights(
    SJPMDItemMasterCaseNetWeight   _net,
    SJPMDItemMasterCaseGrossWeight _gross)
{
    this.setField(fieldNum(SJPMDItemMaster, oc_net_weight), _net);
    return this.setField(fieldNum(SJPMDItemMaster, oc_gross_weight), _gross);
}
